      'faq_1_q': "શું ક્વોટેશન કિંમતમાં GST શામેલ છે?",
      'faq_1_a': "હા. તમામ CCTVQuotation ક્વોટેશનમાં 18% GST શામેલ છે, કોઈ છુપાયેલ ખર્ચ નથી. કિંમતમાં કેમેરા, DVR/NVR, HDD, કેબલિંગ અને વ્યાવસાયિક ઇન્સ્ટોલેશન શામેલ છે — બધું જ.",
