      'faq_4_a': "હા. અમે CP Plus અને Prama કેમેરા ઇન્સ્ટોલ કરીએ છીએ જે BIS-ER પ્રમાણપત્ર ધરાવે છે — જે સરકારી ટેન્ડર, હાઉસિંગ સોસાયટીઓ અને વ્યાવસાયિક પ્રોજેક્ટ્સ માટે યોગ્ય છે.",
