    "wz_since_you_already_have_a_syste": "ଯେହେତୁ ଆପଣଙ୍କ ପାଖରେ ଅଲରେଡି ଗୋଟିଏ ସିଷ୍ଟମ୍ ଅଛି, ନୂଆ କ୍ୟାମେରା ଆଡ୍ କରିବା ପୂର୍ବରୁ ଆମ ଇଞ୍ଜିନିୟରଙ୍କୁ ଆପଣଙ୍କର ଏକ୍ସିଷ୍ଟିଂ DVR ର କମ୍ପାଟିବିଲିଟି ଚେକ୍ କରିବାକୁ ପଡିବ।",
    "wz_we_need_to_check_your_systems_": "ଆମକୁ ଆପଣଙ୍କ ସିଷ୍ଟମ୍‌ର କମ୍ପାଟିବିଲିଟି ଚେକ୍ କରିବାକୁ ପଡିବ!",
