    "wz_do_you_know_the_technical_spec": "ଆପଣ ଆପଣଙ୍କ ଏକ୍ସିଷ୍ଟିଂ ସିଷ୍ଟମ୍‌ର ଟେକ୍ନିକାଲ୍ ସ୍ପେସିଫିକେସନ୍ ଜାଣିଛନ୍ତି କି?",
    "wz_i_already_have_a_cctv_system_a": "ମୋ ପାଖରେ ଅଲରେଡି ଗୋଟିଏ CCTV ସିଷ୍ଟମ୍ ଅଛି ଏବଂ ମୁଁ ଆହୁରି ଅଧିକ କ୍ୟାମେରା ଆଡ୍ କରିବାକୁ ଚାହୁଁଛି।",
