    "wz_i_already_know_exactly_what_ca": "କେଉଁ କ୍ୟାମେରା ଏବଂ ଟେକ୍ନିକାଲ୍ ସ୍ପେସିଫିକେସନ୍ ଦରକାର ତାହା ମୁଁ ଏକ୍ଜାକ୍ଟଲି ଜାଣିଛି। ମୋତେ କାଟାଲଗ୍‌ରୁ ମୋର ନିଜର କଷ୍ଟମ୍ ପ୍ୟାକେଜ୍ ବିଲ୍ଡ କରିବାକୁ ଦିଅନ୍ତୁ।",
