    "wz_choose_between_our_easy_guided": "କଷ୍ଟମ୍ କନଫିଗରେସନ୍ ପାଇଁ ଆମର ଇଜି ଗାଇଡେଡ୍ ସେଟଅପ୍ କିମ୍ବା ଆମର ଆଡଭାନ୍ସଡ୍ ପ୍ରୋଫେସନାଲ୍ ବିଲ୍ଡର୍ ଭିତରୁ ଚୁଜ୍ କରନ୍ତୁ।",
